  #define ASTEROID_SHAPE_OCTAVES 2

  // Хеш vec3 → float (Dave Hoskins). Стабильный сид формы из позиции инстанса.
  float hash13(vec3 p3) {
    p3 = fract(p3 * 0.1031);
    p3 += dot(p3, p3.zyx + 31.32);
    return fract((p3.x + p3.y) * p3.z);
  }

  // fbm производного шума: vec4(value, gradient). Градиент домена учитывает
  // частоту октавы (цепное правило d/dp snoiseGrad(p·freq)).
  vec4 fbmGrad(vec3 p) {
    vec4 sum = vec4(0.0);
    float amp = 0.5;
    float freq = 1.0;
    for (int o = 0; o < ASTEROID_SHAPE_OCTAVES; o++) {
      vec4 nv = snoiseGrad(p * freq);
      sum.x += amp * nv.x;
      sum.yzw += amp * freq * nv.yzw;
      amp *= 0.5;
      freq *= 2.0;
    }
    return sum;
  }

  // Остаточная деформация: НЕ формообразование (силуэт несёт запечённый
  // архетип), а лёгкая пер-инстансная рябь — декоррелирует повторы K мешей.
  // Смещение вдоль направления (сохраняет звёздность запечённой формы),
  // нормаль — тангенциальное возмущение ЗАПЕЧЁННОЙ нормали с мягким клампом.
  void deformAsteroid(vec3 pos, vec3 normal, float seed, float amp, out vec3 displacedPos, out vec3 newNormal) {
    float R = length(pos);
    vec3 dir = pos / max(R, 1e-6);

    vec3 domain = dir * uShapeFreq + vec3(seed * 17.13, seed * 5.71, seed * 9.37);
    // LOD detail weight can make amp exactly zero. Keep the position/normal
    // reconstruction below, but skip both noise octaves that contribute nothing.
    // No epsilon: tiny and negative nonzero amplitudes retain their deformation.
    vec4 nv = vec4(0.0);
    if (amp != 0.0) {
      nv = fbmGrad(domain);
    }

    displacedPos = dir * (R * (1.0 + amp * nv.x));

    vec3 gdisp = amp * nv.yzw;
    vec3 gTangent = gdisp - dot(gdisp, normal) * normal;
    gTangent /= 1.0 + length(gTangent);
    newNormal = normalize(normal - gTangent);
  }


  uniform float uSpinPeriod;
  uniform float uSpinTime;

  mat3 asteroidSpinMatrix(float shapeSeed) {
    mat3 spin = mat3(1.0);
    if (uSpinPeriod > 0.0) {
      vec3 spinAxis = normalize(vec3(
        hashSurface11(shapeSeed + 13.13),
        hashSurface11(shapeSeed + 17.17),
        hashSurface11(shapeSeed + 19.19)
      ) * 2.0 - 1.0);
      float m = min(6.0 + floor(hashSurface11(shapeSeed + 23.23) * 13.0), 18.0);
      float spinAngle = 2.0 * PI * (uSpinTime * (m / 12.0) / uSpinPeriod + hashSurface11(shapeSeed + 29.29));
      float cosA = cos(spinAngle);
      float sinA = sin(spinAngle);
      spin = cosA * mat3(1.0) + sinA * mat3(0.0, spinAxis.z, -spinAxis.y, -spinAxis.z, 0.0, spinAxis.x, spinAxis.y, -spinAxis.x, 0.0) + (1.0 - cosA) * outerProduct(spinAxis, spinAxis);
    }
    return spin;
  }

  mat3 asteroidNormalMatrix(mat3 instanceLinear, mat3 spin) {
    return transpose(inverse(instanceLinear)) * spin;
  }


    void main() {
      // Деформация силуэта: сид рисунка контура — хеш от МЕСТНОЙ позиции
      // инстанса (в своём секторе): она у камня не меняется при переезде
      // плавающего начала, а instanceOrigin меняется — сид от суммы
      // перещёлкивал бы форму всех камней разом. У колец начало нулевое, и
      // выражение то же, что было.
      // Амплитуда — второй, декоррелированный хеш той же позиции → каждый
      // камень получает свою «изрезанность» из диапазона [min,max].
      if (abs(determinant(mat3(instanceMatrix))) < 1e-20) { gl_Position = vec4(2.0, 2.0, 2.0, 1.0); return; }
      vAsteroidDetailWeight = 1.0;
      if (uImpostorReady > 0.5 && instanceDetailEnd > 0.0) {
        vec3 cameraLocal = -inverse(mat3(modelViewMatrix)) * modelViewMatrix[3].xyz;
        vec3 cameraDelta = instanceOrigin + instanceMatrix[3].xyz - cameraLocal;
        float distance = uLodVolumetric > 0.5 ? length(cameraDelta) : length(cameraDelta.xz);
        float q = 1.0 - smoothstep(uDetailStartFraction * instanceDetailEnd, instanceDetailEnd, distance);
        vAsteroidDetailWeight = q * instanceDetailMix;
      }
      float shapeSeed = hash13(instanceMatrix[3].xyz);
      float ampSeed = hash13(instanceMatrix[3].xyz * 1.37 + 11.7);
      float shapeAmp = mix(uShapeAmpMin, uShapeAmpMax, ampSeed) * vAsteroidDetailWeight;
      vec3 shapedPos;
      vec3 shapedNormal;
      deformAsteroid(position, normal, shapeSeed, shapeAmp, shapedPos, shapedNormal);

      // Вращение вокруг оси из того же хеша, что форма (shapeSeed — значение
      // вершинника, НЕ варьинг: ULP-джиттер интерполяции сюда не попадает).
      // uSpinPeriod <= 0 — блок не исполняется, всё ниже тождественно прежнему
      // (кольца по умолчанию).
      //
      // Поза ДО вращения — домен узора и трипланара (vObjectPos/vObjectNormal):
      // текстура привязана к камню. Из повёрнутой позы узор стоял бы в
      // пространстве, а камень крутился под ним. Само вращение — матрицей в
      // vObjToView: освещение видит повёрнутую нормаль
      vec3 restPos = shapedPos;
      vec3 restNormal = shapedNormal;
      mat3 spin = asteroidSpinMatrix(shapeSeed);
      shapedPos = spin * restPos;

      vec4 worldPosition = instanceMatrix * vec4(shapedPos, 1.0);
      // Абсолютная позиция в системе кольца: смещение сектора + локальная
      worldPosition.xyz += instanceOrigin;
      vec4 mvPosition = modelViewMatrix * worldPosition;

      gl_Position = projectionMatrix * mvPosition;

      // Ring-local позиция фрагмента для модели пыли/тени (пофрагментная) —
      // от ЦЕНТРА КОЛЬЦА, а не от плавающего начала: прибавляем его смещение.
