    vec3 oi = vec3(-1.0, 0.0, 1.0);
    vec3 of = vec3(-0.5, 0.5, 1.5);
    vec3 px = cellular_permute(Pi.x + oi);
    float F1 = 1e6; float F2 = 1e6;
    vec3 bestD = vec3(0.0, 0.0, 1.0);
    float bestHash = 0.0;
    for (int i = 0; i < 3; i++) {
      vec3 p = cellular_permute(px[i] + Pi.y + oi);
      for (int j = 0; j < 3; j++) {
        vec3 pp = cellular_permute(p[j] + Pi.z + oi);
        vec3 ox = fract(pp * K) - Ko;
        vec3 oy = mod(floor(pp * K), 7.0) * K - Ko;
        vec3 pz = cellular_permute(pp);
        vec3 oz = fract(pz * K) - Ko;
        vec3 dx = Pf.x - of[i] + jitter * ox;
        vec3 dy = Pf.y - of[j] + jitter * oy;
        for (int k = 0; k < 3; k++) {
          float dz = Pf.z - of[k] + jitter * oz[k];
          float d = dx[k] * dx[k] + dy[k] * dy[k] + dz * dz;
          if (d < F1) {
            F2 = F1; F1 = d;
            bestD = vec3(dx[k], dy[k], dz);
            bestHash = pz[k] * (1.0 / 289.0);
          } else if (d < F2) {
            F2 = d;
          }
        }
      }
    }
    toNearest = normalize(bestD + vec3(1e-6, 0.0, 0.0));
    return vec4(sqrt(F1), sqrt(F2), bestHash, 0.0);
  }

  // Производный 3D симплекс-шум: возвращает vec4(value, gradient).
  // Значение в том же масштабе, что snoise(vec3); градиент — аналитическая
  // производная simplex-noise (Gustavson): d/dv 42·Σ m^4·(p·x).
  vec4 snoiseGrad(vec3 v) {
    const vec2 C = vec2(1.0/6.0, 1.0/3.0);
    const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);

    vec3 i  = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);

    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);

    vec3 x1 = x0 - i1 + 1.0 * C.xxx;
    vec3 x2 = x0 - i2 + 2.0 * C.xxx;
    vec3 x3 = x0 - 1.0 + 3.0 * C.xxx;

    i = mod(i, 289.0);
    vec4 p = permute(permute(permute(
               i.z + vec4(0.0, i1.z, i2.z, 1.0))
             + i.y + vec4(0.0, i1.y, i2.y, 1.0))
             + i.x + vec4(0.0, i1.x, i2.x, 1.0));

    float n_ = 1.0/7.0;
    vec3 ns = n_ * D.wyz - D.xzx;

    vec4 j = p - 49.0 * floor(p * ns.z * ns.z);

    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_);

    vec4 x = x_ * ns.x + ns.yyyy;
    vec4 y = y_ * ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);

    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);

    vec4 s0 = floor(b0) * 2.0 + 1.0;
    vec4 s1 = floor(b1) * 2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));

    vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;

    vec3 p0 = vec3(a0.xy, h.x);
    vec3 p1 = vec3(a0.zw, h.y);
    vec3 p2 = vec3(a1.xy, h.z);
    vec3 p3 = vec3(a1.zw, h.w);

    vec4 norm = taylorInvSqrt(vec4(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3)));
    p0 *= norm.x;
    p1 *= norm.y;
    p2 *= norm.z;
    p3 *= norm.w;

    vec4 m  = max(0.6 - vec4(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), 0.0);
    vec4 m2 = m * m;
    vec4 m4 = m2 * m2;
    vec4 pdotx = vec4(dot(p0, x0), dot(p1, x1), dot(p2, x2), dot(p3, x3));

    float value = 42.0 * dot(m4, pdotx);

    // grad = 42·Σ [ -8·m^3·(p·x)·x  +  m^4·p ]
    vec4 temp = m2 * m * pdotx; // m^3 · (p·x)
    vec3 grad = -8.0 * (temp.x * x0 + temp.y * x1 + temp.z * x2 + temp.w * x3);
    grad += m4.x * p0 + m4.y * p1 + m4.z * p2 + m4.w * p3;
    grad *= 42.0;

    return vec4(value, grad);
  }

  #endif


  // Композит облика: макро-альбедо (джиттер + мотл + maria). dir — нормали-
  // зованная объектная позиция (домен); tintSeed/domainOffset — пер-инстансные
  // хеши, вычисленные в ВЕРШИННИКЕ (см. докблок модуля про ULP-джиттер).
  vec3 applyAsteroidSurface(vec3 dir, float tintSeed, vec3 domainOffset, vec3 baseColor, float colorJitter, float tintStrength, float mariaStrength) {
    // База профиля + тонкий per-instance джиттер яркости + внутриповерхностный мотл
    vec3 base = baseColor * (1.0 + colorJitter * (tintSeed - 0.5) * 2.0);
    float mottle = snoise(dir * 2.0 + domainOffset);
    base *= 1.0 + tintStrength * mottle * 0.5;

    // Крупномасштабное альбедо (maria/highlands): НЧ-маска делит поверхность на
    // тёмные базальтовые равнины (maria) и светлые возвышенности → макро-
    // композиция, поверхность перестаёт читаться как равномерный шум. Частоты
    // низкие, поэтому маска стабильна на расстоянии (не мельтешит). Модулирует
    // ТОЛЬКО базовый цвет — PBR-микрослой ложится поверх.
    float mariaField = 0.7 * snoise(dir * 1.2 + domainOffset * 0.7)
                     + 0.3 * snoise(dir * 2.6 + domainOffset * 1.9);
    float maria = smoothstep(-0.15, 0.35, mariaField);   // мягкие «берега» регионов
    base *= 1.0 - mariaStrength * maria;                 // равнины темнее

    return base;
  }


  // Диффуз реголита: NdotL/NdotV — косинусы к свету и к камере, cosPhase = dot(L, V)
  float asteroidRegolithDiffuse(float NdotL, float NdotV, float cosPhase, float lunarMix, float surge) {
    float nl = max(NdotL, 0.0);
    float nv = max(NdotV, 0.0);
    float lambert = nl;
    float lommel = 2.0 * nl / max(nl + nv, 1e-4);
    float diffuse = mix(lambert, lommel, lunarMix);
    float g = acos(clamp(cosPhase, -1.0, 1.0));
    float opposition = 1.0 + surge * exp(-g / 0.1);
    return diffuse * opposition;
  }

  // Planetshine: N и dirPlanet — в одном пространстве (view), ringPos и
  // lightDirRing — в ring-local (планета в начале координат), planetRadius —
  // в единицах ringPos. Возвращает множитель альбедо
  float asteroidPlanetshine(vec3 N, vec3 dirPlanet, vec3 ringPos, vec3 lightDirRing, float planetRadius) {
    float d = length(ringPos);
    if (planetRadius <= 0.0 || d <= planetRadius) return 0.0;
    vec3 pHat = ringPos / d;
    float phase = 0.5 * (1.0 + dot(pHat, lightDirRing));
    float angR = planetRadius / d;
    float solid = angR * angR;
    float wrap = angR;
    float wrapped = max(dot(N, dirPlanet) + wrap, 0.0) / (1.0 + wrap);
    return phase * solid * wrapped;
  }

  // Подсветка от листа кольца: N и ringNormalView — view, ringPos и lightDirRing —
  // ring-local (лист — плоскость y = 0), tau/sheetColor — по радиусу камня,
  // halfThickness — полутолщина слоя. Возвращает RGB-множитель альбедо
  vec3 asteroidRingshine(vec3 N, vec3 ringNormalView, vec3 ringPos, vec3 lightDirRing, float tau, vec3 sheetColor, float halfThickness) {
    float mu0 = abs(lightDirRing.y);
    if (mu0 < 1e-3 || tau <= 0.0) return vec3(0.0);
    float eps = max(0.05 * halfThickness, 1e-9);
    float lit = mu0 * (1.0 - exp(-tau / mu0));
    float through = tau * exp(-tau / mu0);
    float sunSide = smoothstep(-eps, eps, ringPos.y * sign(lightDirRing.y));
    float sheet = mix(through, lit, sunSide);
    vec3 toSheet = -clamp(ringPos.y / eps, -1.0, 1.0) * ringNormalView;
    float facing = 0.5 * (1.0 + dot(N, toSheet));
    return sheetColor * (sheet * facing);
  }


  uniform sampler2D uRockDiffMap;
  uniform sampler2D uRockNorMap;
  uniform sampler2D uRockArmMap;
  uniform float uDetailMapsEnabled;
  uniform float uDetailScale;
  uniform float uDetailSaturation;
  uniform float uDetailBrightness;
  uniform float uDetailNormalScale;
  uniform float uDetailAoInfluence;
  uniform float uDetailRoughInfluence;


  // Веса проекций: степень 4 прижимает бленд к доминирующей оси — меньше
  // «двоения» текстуры на диагональных нормалях
  vec3 triplanarWeights(vec3 objNormal) {
    vec3 w = pow(abs(objNormal), vec3(4.0));
    return w / (w.x + w.y + w.z);
  }

  // Ядро бленда albedo/ARM: одинаковая математика для обеих карт (взвешенная
  // сумма трёх проекций), поэтому одна функция на двоих — вызывающая сторона
  // сама решает, что читать (albedo или ARM).
  vec3 triplanarBlendRgb(vec3 cx, vec3 cy, vec3 cz, vec3 w) {
    return cx * w.x + cy * w.y + cz * w.z;
  }

  // Whiteout-бленд нормалей: тангенциальные компоненты суммируются с геом.
  // нормалью по осям проекции, z-компоненты перемножаются — швов между
  // проекциями нет, «плоского» усреднения тоже. tx/ty/tz — уже распакованные
  // ([-1,1]) значения проекций, выбор способа их получить (обычная выборка
  // или стохастическая) — забота вызывающей стороны.
  vec3 triplanarBlendNormal(vec3 tx, vec3 ty, vec3 tz, vec3 n, vec3 w) {
    tx = vec3(tx.xy + n.zy, abs(tx.z) * n.x);
    ty = vec3(ty.xy + n.xz, abs(ty.z) * n.y);
    tz = vec3(tz.xy + n.xy, abs(tz.z) * n.z);
    return normalize(tx.zyx * w.x + ty.xzy * w.y + tz.xyz * w.z);
  }

  vec3 triplanarAlbedo(sampler2D map, vec3 p, vec3 w, vec2 offset) {
    vec3 cx = texture2D(map, p.zy * uDetailScale + offset).rgb;
    vec3 cy = texture2D(map, p.xz * uDetailScale + offset).rgb;
    vec3 cz = texture2D(map, p.xy * uDetailScale + offset).rgb;
    return triplanarBlendRgb(cx, cy, cz, w);
  }

  vec3 triplanarArm(sampler2D map, vec3 p, vec3 w, vec2 offset) {
    vec3 ax = texture2D(map, p.zy * uDetailScale + offset).rgb;
    vec3 ay = texture2D(map, p.xz * uDetailScale + offset).rgb;
    vec3 az = texture2D(map, p.xy * uDetailScale + offset).rgb;
    return triplanarBlendRgb(ax, ay, az, w);
  }

  vec3 triplanarNormal(sampler2D map, vec3 p, vec3 n, vec3 w, vec2 offset) {
    vec3 tx = texture2D(map, p.zy * uDetailScale + offset).xyz * 2.0 - 1.0;
    vec3 ty = texture2D(map, p.xz * uDetailScale + offset).xyz * 2.0 - 1.0;
    vec3 tz = texture2D(map, p.xy * uDetailScale + offset).xyz * 2.0 - 1.0;
    return triplanarBlendNormal(tx, ty, tz, n, w);
  }


  uniform vec3 uDustColor;
  uniform float uDustDensity;
  uniform float uDustScaleHeight;
  uniform float uDustRingInner;
  uniform float uDustRingOuter;
  uniform vec3 uDustCamRingPos;
  uniform vec3 uDustLightDirRing;
  uniform float uDustAnglePower;
  uniform float uDustNearFade;
  uniform float uDustPlanetRadius;
  uniform sampler2D uDustRadialMap;
  uniform float uDustRadialMapScale;
  // Полосы кольца (RGB — цвет, A — альфа; см. RingBandTexture): 0 — текстуры нет,
  // тинт и самозатенение слоя выключены
  uniform sampler2D uRingBandMap;
  uniform float uRingBandEnabled;
  uniform vec3 uBandMeanColor;
  uniform float uBandTintStrength;
  // Слой кольца: полутолщина (ring-local) и сила самозатенения (множитель τ)
  uniform float uLayerHalfThickness;
  uniform float uLayerShadowStrength;


  // Маска кромок кольца × радиальный профиль из альфы текстуры кольца.
  // Профиль (uDustRadialMap, R-канал; тот же маппинг u, что у RingShader)
  // согласует пыль с субкольцами; нормирован на среднее 1 через
  // uDustRadialMapScale, чтобы калибровка tau грейзинг-луча не поплыла.
  // Scale 0 → профиль выключен (равномерная пыль, поведение до A-lite).
  // CPU-зеркало: radialMask в tests/ringDust/tauMirror.ts — менять синхронно.
  float ringDustRadialMask(float r) {
    float edge = (uDustRingOuter - uDustRingInner) * 0.12;
    float mask = smoothstep(uDustRingInner, uDustRingInner + edge, r)
               * (1.0 - smoothstep(uDustRingOuter - edge, uDustRingOuter, r));
    if (uDustRadialMapScale > 0.0) {
      float u = clamp((r - uDustRingInner) / (uDustRingOuter - uDustRingInner), 0.0, 1.0);
      mask *= texture2D(uDustRadialMap, vec2(u, 0.5)).r * uDustRadialMapScale;
    }
    return mask;
  }

  // Плотность пыли в точке ring-local space (сэмплируется маршем объёма)
  float ringDustDensityAt(vec3 p) {
    float safeH = max(uDustScaleHeight, 1e-6);
    return uDustDensity * ringDustRadialMask(length(p.xz)) * exp(-abs(p.y) / safeH);
  }

  // Гейт по углу луча к плоскости кольца: 1 на скользящем, строго 0 при 90°.
  // Нефизичный, осознанный: лечит «тусклую пелену сверху» (см. спеку v2)
  float ringDustAngleGate(vec3 dir) {
    return pow(max(1.0 - abs(dir.y), 0.0), uDustAnglePower);
  }

  // Рамп ближней дистанции: вблизи камеры пыль не проявляется
  float ringDustNearRamp(float t) {
    return smoothstep(0.0, max(uDustNearFade, 1e-6), t);
  }

  // Интервал t, где луч (в проекции XZ) внутри цилиндра радиуса R.
  // Пустой интервал кодируется как vec2(1.0, 0.0)
  vec2 ringDustCircleInterval(vec3 o, vec3 d, float R) {
    float a = dot(d.xz, d.xz);
    if (a < 1e-12) {
      // Вертикальный луч: внутри цилиндра целиком либо никогда
      return length(o.xz) <= R ? vec2(-1.0e9, 1.0e9) : vec2(1.0, 0.0);
    }
    float b = dot(o.xz, d.xz);
    float c = dot(o.xz, o.xz) - R * R;
    float disc = b * b - a * c;
    if (disc <= 0.0) return vec2(1.0, 0.0);
    float sq = sqrt(disc);
    return vec2((-b - sq) / a, (-b + sq) / a);
  }

  // --- Слой кольца: самозатенение и тинт по полосам (общее для камней и марша) ---
  // CPU-зеркало: layerTau/columnFraction/layerShadow/bandTint в tests/ringDust/tauMirror.ts

  // Выборка полос по радиусу (тот же маппинг u, что у RingShader)
  vec4 ringBandAt(float r) {
    float u = clamp((r - uDustRingInner) / (uDustRingOuter - uDustRingInner), 0.0, 1.0);
    return texture2D(uRingBandMap, vec2(u, 0.5));
  }

  // Оптическая толща слоя по нормали на радиусе: пропускание = 1 − α
  float ringLayerTau(float r) {
    if (uRingBandEnabled < 0.5) return 0.0;
    float a = ringBandAt(r).a;
    return -log(1.0 - min(a, 0.98));
  }

  // Доля столба слоя НАД точкой в сторону солнца при треугольном вертикальном
  // распределении камней (пик в средней плоскости, ноль на ±half)
  float ringLayerColumnFraction(float ySun) {
    float u = clamp(ySun / max(uLayerHalfThickness, 1e-9), -1.0, 1.0);
    return u >= 0.0 ? (1.0 - u) * (1.0 - u) * 0.5 : 1.0 - (1.0 + u) * (1.0 + u) * 0.5;
  }

  // Самозатенение слоя: камни и пыль над точкой вдоль направления на звезду.
  // Путь через слой делится на синус высоты звезды над плоскостью (пол 0.2).
  // Физическая экспонента СМЕШИВАЕТСЯ с единицей по uLayerShadowStrength, а не
  // множит толщу: рендер показывает и глубокие камни, которых в оптически
  // плотном слое не видно, и честная толща Сатурна (α ≈ 1, солнце ≤ 27° над
  // плоскостью) красила их в чёрное. При силе s худший случай — (1 − s)
  float ringLayerShadow(vec3 p) {
    float tau = ringLayerTau(length(p.xz));
    if (tau <= 0.0 || uLayerShadowStrength <= 0.0) return 1.0;
    float ySun = uDustLightDirRing.y >= 0.0 ? p.y : -p.y;
    float sinE = max(abs(uDustLightDirRing.y), 0.2);
    float physical = exp(-tau * ringLayerColumnFraction(ySun) / sinE);
    return mix(1.0, physical, uLayerShadowStrength);
  }

  // Тинт альбедо по цвету полосы относительно среднего цвета кольца:
  // светлые ледяные полосы — светлые камни, тёмные пыльные — тёмные
  vec3 ringBandTint(float r) {
    if (uRingBandEnabled < 0.5) return vec3(1.0);
    vec3 band = ringBandAt(r).rgb;
    vec3 tint = clamp(band / max(uBandMeanColor, vec3(0.05)), 0.5, 1.5);
    return mix(vec3(1.0), tint, uBandTintStrength);
  }

  // Цвет дымки: базовый + мягкий forward-scattering буст в сторону звезды.
  // Единственный прямой член света звезды на пыль — красится целиком.
  // sun — доля прямого лепестка [0, 1]: pow(dot(луч, на звезду), 4)
  vec3 ringDustHazeSun(float sun) {
    #ifdef USE_LIGHT_TINT
      return uDustColor * (0.75 + 0.45 * sun) * uLightColor;
    #else
      return uDustColor * (0.75 + 0.45 * sun);
    #endif
  }

  vec3 ringDustHaze(vec3 rayDir) {
    return ringDustHazeSun(pow(max(dot(rayDir, uDustLightDirRing), 0.0), 4.0));
  }

  // Тень планеты на пыль: аналитический теневой цилиндр вдоль направления на
  // звезду. uDustLightDirRing — от центра планеты (= начало ring-local) к звезде,
  // планета в начале координат. Зеркалит getShadowFromSphere из RingShaderTemplate,
  // чтобы тень пыли совпадала с тенью 2D-кольца; мягкая кромка полутени вместо
  // жёсткой. Возвращает множитель яркости: 0.04 в умбре → 1.0 вне тени.
  float ringDustPlanetShadow(vec3 p) {
    if (uDustPlanetRadius <= 0.0) return 1.0;
    float pDotS = dot(p, uDustLightDirRing);
    if (pDotS >= 0.0) return 1.0; // солнечная сторона — не в тени
    float perp = sqrt(max(dot(p, p) - pDotS * pDotS, 0.0));
    float penumbra = uDustPlanetRadius * 0.08;
    float shade = smoothstep(uDustPlanetRadius, uDustPlanetRadius + penumbra, perp);
    return mix(0.04, 1.0, shade);
  }

  float ringDustMaskAtT(vec3 o, vec3 d, float t) {
    return ringDustRadialMask(length(o.xz + d.xz * t));
  }

  // Нечётная первообразная exp(-|u|/H): F(u) = sign(u) * H * (1 - exp(-|u|/H))
  float ringDustF(float u) {
    // защита от деления на ноль
    float safeH = max(uDustScaleHeight, 1e-6);
    float f = safeH * (1.0 - exp(-abs(u) / safeH));
    return u >= 0.0 ? f : -f;
  }

  // Замкнутая форма интеграла exp(-|y(t)|/H) dt по [t0, t1], y(t) = oy + dy*t
  float ringDustVerticalIntegral(float oy, float dy, float t0, float t1) {
    if (t1 <= t0) return 0.0;
    if (abs(dy) < 1e-8) {
      float safeH = max(uDustScaleHeight, 1e-6);
      return exp(-abs(oy) / safeH) * (t1 - t0);
    }
    float ya = oy + dy * t0;
    float yb = oy + dy * t1;
    return (ringDustF(max(ya, yb)) - ringDustF(min(ya, yb))) / abs(dy);
  }

  // Средняя маска кромок по куску с монотонным |y(t)|: тапы по квантилям
  // экспоненциальной массы (важностная выборка — маска сэмплируется там,
  // где сосредоточен вклад в интеграл)
  float ringDustPieceMask(vec3 o, vec3 d, float t0, float t1) {
    float L = t1 - t0;
    float absDy = abs(d.y);
    if (absDy < 1e-8) {
      return 0.25 * (ringDustMaskAtT(o, d, t0 + L * 0.125)
                   + ringDustMaskAtT(o, d, t0 + L * 0.375)
                   + ringDustMaskAtT(o, d, t0 + L * 0.625)
                   + ringDustMaskAtT(o, d, t0 + L * 0.875));
    } else {
      // Keep both texture-sampling returns in explicit branches. ANGLE/D3D11
      // reports X4000 on the function return with an early return + fallthrough.
      float ya = abs(o.y + d.y * t0);
      float yb = abs(o.y + d.y * t1);
      // Масса концентрируется у конца с меньшим |y|
      float tNear = ya <= yb ? t0 : t1;
      float dirSign = ya <= yb ? 1.0 : -1.0;
      float safeH = max(uDustScaleHeight, 1e-6);
      float lambda = safeH / absDy;
      float A = max(1.0 - exp(-L / lambda), 1e-6);
      vec4 dist = -lambda * log(vec4(1.0) - vec4(0.125, 0.375, 0.625, 0.875) * A);
      vec4 tq = vec4(tNear) + dirSign * min(dist, vec4(L));
      return 0.25 * (ringDustMaskAtT(o, d, tq.x) + ringDustMaskAtT(o, d, tq.y)
                   + ringDustMaskAtT(o, d, tq.z) + ringDustMaskAtT(o, d, tq.w));
