      float m = min(6.0 + floor(hashSurface11(shapeSeed + 23.23) * 13.0), 18.0);
      float spinAngle = 2.0 * PI * (uSpinTime * (m / 12.0) / uSpinPeriod + hashSurface11(shapeSeed + 29.29));
      float cosA = cos(spinAngle);
