    float eps = max(0.05 * halfThickness, 1e-9);
    float lit = mu0 * (1.0 - exp(-tau / mu0));
    float through = tau * exp(-tau / mu0);
    float sunSide = smoothstep(-eps, eps, ringPos.y * sign(lightDirRing.y));
