  // Композит облика: макро-альбедо (джиттер + мотл + maria). dir — нормали-
  // зованная объектная позиция (домен); tintSeed/domainOffset — пер-инстансные
  // хеши, вычисленные в ВЕРШИННИКЕ (см. докблок модуля про ULP-джиттер).
  vec3 applyAsteroidSurface(vec3 dir, float tintSeed, vec3 domainOffset, vec3 baseColor, float colorJitter, float tintStrength, float mariaStrength) {
    // База профиля + тонкий per-instance джиттер яркости + внутриповерхностный мотл
    vec3 base = baseColor * (1.0 + colorJitter * (tintSeed - 0.5) * 2.0);
    float mottle = snoise(dir * 2.0 + domainOffset);
    base *= 1.0 + tintStrength * mottle * 0.5;

    // Крупномасштабное альбедо (maria/highlands): НЧ-маска делит поверхность на
    // тёмные базальтовые равнины (maria) и светлые возвышенности → макро-
    // композиция, поверхность перестаёт читаться как равномерный шум. Частоты
    // низкие, поэтому маска стабильна на расстоянии (не мельтешит). Модулирует
    // ТОЛЬКО базовый цвет — PBR-микрослой ложится поверх.
    float mariaField = 0.7 * snoise(dir * 1.2 + domainOffset * 0.7)
                     + 0.3 * snoise(dir * 2.6 + domainOffset * 1.9);
    float maria = smoothstep(-0.15, 0.35, mariaField);   // мягкие «берега» регионов
    base *= 1.0 - mariaStrength * maria;                 // равнины темнее

    return base;
  }


  uniform sampler2D uRockDiffMap;
  uniform sampler2D uRockNorMap;
  uniform sampler2D uRockArmMap;
  uniform float uDetailMapsEnabled;
  uniform float uDetailScale;
  uniform float uDetailSaturation;
  uniform float uDetailBrightness;
  uniform float uDetailNormalScale;
  uniform float uDetailAoInfluence;
  uniform float uDetailRoughInfluence;


  // Веса проекций: степень 4 прижимает бленд к доминирующей оси — меньше
  // «двоения» текстуры на диагональных нормалях
  vec3 triplanarWeights(vec3 objNormal) {
    vec3 w = pow(abs(objNormal), vec3(4.0));
    return w / (w.x + w.y + w.z);
  }

  // Ядро бленда albedo/ARM: одинаковая математика для обеих карт (взвешенная
  // сумма трёх проекций), поэтому одна функция на двоих — вызывающая сторона
  // сама решает, что читать (albedo или ARM).
  vec3 triplanarBlendRgb(vec3 cx, vec3 cy, vec3 cz, vec3 w) {
    return cx * w.x + cy * w.y + cz * w.z;
  }

  // Whiteout-бленд нормалей: тангенциальные компоненты суммируются с геом.
  // нормалью по осям проекции, z-компоненты перемножаются — швов между
  // проекциями нет, «плоского» усреднения тоже. tx/ty/tz — уже распакованные
  // ([-1,1]) значения проекций, выбор способа их получить (обычная выборка
  // или стохастическая) — забота вызывающей стороны.
  vec3 triplanarBlendNormal(vec3 tx, vec3 ty, vec3 tz, vec3 n, vec3 w) {
    tx = vec3(tx.xy + n.zy, abs(tx.z) * n.x);
    ty = vec3(ty.xy + n.xz, abs(ty.z) * n.y);
    tz = vec3(tz.xy + n.xy, abs(tz.z) * n.z);
    return normalize(tx.zyx * w.x + ty.xzy * w.y + tz.xyz * w.z);
  }

  vec3 triplanarAlbedo(sampler2D map, vec3 p, vec3 w, vec2 offset) {
    vec3 cx = texture2D(map, p.zy * uDetailScale + offset).rgb;
    vec3 cy = texture2D(map, p.xz * uDetailScale + offset).rgb;
    vec3 cz = texture2D(map, p.xy * uDetailScale + offset).rgb;
    return triplanarBlendRgb(cx, cy, cz, w);
  }

  vec3 triplanarArm(sampler2D map, vec3 p, vec3 w, vec2 offset) {
    vec3 ax = texture2D(map, p.zy * uDetailScale + offset).rgb;
    vec3 ay = texture2D(map, p.xz * uDetailScale + offset).rgb;
    vec3 az = texture2D(map, p.xy * uDetailScale + offset).rgb;
    return triplanarBlendRgb(ax, ay, az, w);
  }

  vec3 triplanarNormal(sampler2D map, vec3 p, vec3 n, vec3 w, vec2 offset) {
    vec3 tx = texture2D(map, p.zy * uDetailScale + offset).xyz * 2.0 - 1.0;
    vec3 ty = texture2D(map, p.xz * uDetailScale + offset).xyz * 2.0 - 1.0;
    vec3 tz = texture2D(map, p.xy * uDetailScale + offset).xyz * 2.0 - 1.0;
    return triplanarBlendNormal(tx, ty, tz, n, w);
  }


  uniform vec3 uDetailAverageDiffuse;
  uniform vec3 uDetailAverageArm;
  struct AsteroidAppearanceProfile {
    vec3 rockColor;
    float specularStrength;
    float specularPower;
    float specularTint;
    float lunarMix;
    float surfaceAmbient;
  };
  vec3 shadeAsteroid(vec3 vObjectPos, vec3 vObjectNormal, mat3 vObjToView,
    vec3 vViewPosition, vec3 vViewLightDirection, vec3 vPlanetDirView, vec3 vRingNormalView,
    vec3 vRingPos, vec2 vSurfaceData, float vTintSeed, vec3 vDomainOffset, vec2 vTriOffset,
    float detailWeight, AsteroidAppearanceProfile profile) {
      vec3 surfDir = normalize(vObjectPos);
      vec3 albedo = applyAsteroidSurface(surfDir, vTintSeed, vDomainOffset, profile.rockColor, uColorJitter, uTintStrength, uMariaStrength);
      albedo *= ringBandTint(length(vRingPos.xz));
      vec3 objN = normalize(vObjectNormal);
      float surfAO = 1.0;
      float specStrength = profile.specularStrength;
      float specPower = profile.specularPower;
      if (uDetailMapsEnabled > 0.5) {
        vec3 geomN = normalize(vObjectNormal);
        vec3 detail = uDetailAverageDiffuse;
        vec3 arm = uDetailAverageArm;
        if (detailWeight > 0.0) {
          vec3 triW = triplanarWeights(geomN);
          vec2 triOffset = vTriOffset;
          detail = mix(detail, triplanarAlbedo(uRockDiffMap, vObjectPos, triW, triOffset), detailWeight);
          arm = mix(arm, triplanarArm(uRockArmMap, vObjectPos, triW, triOffset), detailWeight);
          vec3 nDetail = triplanarNormal(uRockNorMap, vObjectPos, geomN, triW, triOffset);
          objN = normalize(objN + detailWeight * uDetailNormalScale * (nDetail - geomN));
        }
        float detailLum = dot(detail, vec3(0.299, 0.587, 0.114));
        vec3 structureTint = mix(vec3(detailLum), detail, uDetailSaturation);
        albedo *= structureTint * uDetailBrightness;
        surfAO *= mix(1.0, arm.r, uDetailAoInfluence);
        float gloss = 1.0 - arm.g * uDetailRoughInfluence;
        specStrength *= gloss;
        specPower = max(specPower * gloss, 2.0);
      }
      albedo *= 1.0 + uFreshnessBrighten * vSurfaceData.x;
      specStrength *= 1.0 + 0.5 * vSurfaceData.x;
      surfAO *= 1.0 - uCavityShade * vSurfaceData.y;
      vec3 normal = normalize(vObjToView * objN);
      if (!gl_FrontFacing) normal = -normal;
      vec3 lightDirection = normalize(vViewLightDirection);
      vec3 viewDir = normalize(vViewPosition);
      float NdotL = dot(normal, lightDirection);
      float NdotV = dot(normal, viewDir);
      float cosPhase = dot(lightDirection, viewDir);
      float lightIntensity = asteroidRegolithDiffuse(NdotL, NdotV, cosPhase, profile.lunarMix, uOppositionSurge);
      float planetShadow = ringDustPlanetShadow(vRingPos);
      float direct = planetShadow * ringLayerShadow(vRingPos);
      float shine = asteroidPlanetshine(normal, normalize(vPlanetDirView), vRingPos, uDustLightDirRing, uDustPlanetRadius);
      #ifdef USE_LIGHT_TINT
        vec3 finalColor = albedo * (lightIntensity * surfAO * direct * uLightColor + profile.surfaceAmbient);
      #else
        vec3 finalColor = albedo * (lightIntensity * surfAO * direct + profile.surfaceAmbient);
      #endif
      finalColor += albedo * uPlanetshineColor * (uPlanetshineStrength * shine * surfAO);
      if (uRingBandEnabled > 0.5 && uRingshineStrength > 0.0) {
        float ringR = length(vRingPos.xz);
        vec3 band = ringBandAt(ringR).rgb;
        vec3 sheetColor = mix(band, pow(band, vec3(2.2)), uRingBandSrgb);
        vec3 ringshine = asteroidRingshine(normal, normalize(vRingNormalView), vRingPos, uDustLightDirRing, ringLayerTau(ringR), sheetColor, uLayerHalfThickness);
        #ifdef USE_LIGHT_TINT
          finalColor += albedo * ringshine * (uRingshineStrength * planetShadow * surfAO) * uLightColor;
        #else
          finalColor += albedo * ringshine * (uRingshineStrength * planetShadow * surfAO);
        #endif
      }
      vec3 halfVec = normalize(lightDirection + viewDir);
      float specNormalVar = dot(dFdx(normal), dFdx(normal)) + dot(dFdy(normal), dFdy(normal));
      float specToksvig = 1.0 / (1.0 + specPower * specNormalVar);
      float specPowerAA = specPower * specToksvig;
      float spec = pow(max(dot(normal, halfVec), 0.0), specPowerAA) * specStrength * specToksvig;
      vec3 specColor = mix(vec3(1.0), albedo, profile.specularTint);
      #ifdef USE_LIGHT_TINT
        finalColor += spec * specColor * uLightColor * max(NdotL, 0.0) * direct;
      #else
        finalColor += spec * specColor * max(NdotL, 0.0) * direct;
      #endif
      finalColor = ringDustApplyFog(finalColor, vRingPos);
      return finalColor;
  }


  vec2 impostorSign(vec2 p) { return mix(vec2(-1.0), vec2(1.0), step(vec2(0.0), p)); }
  mat3 impostorFrameBasis(float frame, float grid) {
    vec2 p = vec2(mod(frame, grid), floor(frame / grid)) / (grid - 1.0) * 2.0 - 1.0;
    vec3 direction = vec3(p, 1.0 - abs(p.x) - abs(p.y));
    if (direction.z < 0.0) direction.xy = (1.0 - abs(direction.yx)) * impostorSign(direction.xy);
    direction = normalize(direction);
    vec3 reference = abs(direction.z) < 0.99 ? vec3(0.0, 0.0, 1.0) : vec3(0.0, 1.0, 0.0);
    vec3 right = normalize(cross(reference, direction));
    return mat3(right, cross(direction, right), direction);
  }


  bool impostorFinite(float value) { return !isnan(value) && !isinf(value); }
  bool impostorInside(vec2 uv) { return all(greaterThanEqual(uv, vec2(0.0))) && all(lessThanEqual(uv, vec2(1.0))); }

  vec2 impostorUv(vec2 uv, float frame, float mip) {
    float tile = uImpostorLayout.y * exp2(-mip);
    vec2 offset = vec2(mod(frame, uImpostorLayout.x), floor(frame / uImpostorLayout.x)) * tile;
    return (offset + clamp(uv * tile, vec2(0.5), vec2(tile - 0.5))) / (uImpostorLayout.x * tile);
  }

  void impostorRead(vec2 uv, float frame, float lod, out vec4 normalDepth, out vec4 surfaceCoverage) {
    float lo = floor(lod), hi = min(lo + 1.0, uImpostorLayout.z), blend = lod - lo;
    vec3 a = vec3(impostorUv(uv, frame, lo), vAtlasParams.x);
    normalDepth = textureLod(uImpostorNormalDepth, a, lo);
    surfaceCoverage = textureLod(uImpostorSurfaceCoverage, a, lo);
    if (blend > 0.0) {
      vec3 b = vec3(impostorUv(uv, frame, hi), vAtlasParams.x);
      normalDepth = mix(normalDepth, textureLod(uImpostorNormalDepth, b, hi), blend);
      surfaceCoverage = mix(surfaceCoverage, textureLod(uImpostorSurfaceCoverage, b, hi), blend);
    }
  }

  vec4 renderImpostor(vec3 rayDx, vec3 rayDy) {
    bool perspective = isPerspectiveMatrix(projectionMatrix);
    vec3 center = vRingPos;
    vec3 origin = -vAtlasViewToObject * center;
    vec3 direction = vAtlasRayPoint;
    vec3 originDx = vec3(0.0), originDy = vec3(0.0);
    if (!perspective) {
      origin += vAtlasRayPoint;
      direction = vAtlasViewToObject * vec3(0.0, 0.0, -1.0);
      originDx = rayDx; originDy = rayDy;
      rayDx = rayDy = vec3(0.0);
    }
    float coverage = 0.0, tSum = 0.0;
    vec3 normalSum = vec3(0.0);
    vec2 surfaceSum = vec2(0.0);
    for (int i = 0; i < 3; i++) {
      float frameWeight = vAtlasWeights[i];
      if (frameWeight <= 0.0) continue;
      float frame = vAtlasFrames[i];
      mat3 basis = impostorFrameBasis(frame, uImpostorLayout.x);
      float denominator = dot(direction, basis[2]);
      if (abs(denominator) < 1e-5 * length(direction)) continue;
      float t = -dot(origin, basis[2]) / denominator;
      vec3 p = origin + direction * t;
      float h = vAtlasParams.y;
      vec2 uv = vec2(dot(p, basis[0]), dot(p, basis[1])) / (2.0 * h) + 0.5;
      vec3 dx = originDx + t * rayDx - direction * ((dot(originDx, basis[2]) + t * dot(rayDx, basis[2])) / denominator);
      vec3 dy = originDy + t * rayDy - direction * ((dot(originDy, basis[2]) + t * dot(rayDy, basis[2])) / denominator);
      vec2 uvDx = vec2(dot(dx, basis[0]), dot(dx, basis[1])) / (2.0 * h);
      vec2 uvDy = vec2(dot(dy, basis[0]), dot(dy, basis[1])) / (2.0 * h);
      float footprint = max(length(uvDx), length(uvDy)) * uImpostorLayout.y;
      float lod = clamp(log2(max(footprint, 1e-8)), 0.0, uImpostorLayout.z);
      if (!impostorInside(uv) || t <= 0.0 || !impostorFinite(t)) continue;
      vec4 n, s;
      impostorRead(uv, frame, lod, n, s);
      if (s.a < 1e-5) continue;
      t = (h * (2.0 * n.a / s.a - 1.0) - dot(origin, basis[2])) / denominator;
      p = origin + direction * t;
      uv = vec2(dot(p, basis[0]), dot(p, basis[1])) / (2.0 * h) + 0.5;
      if (!impostorInside(uv) || t <= 0.0 || !impostorFinite(t)) continue;
      impostorRead(uv, frame, lod, n, s);
      if (s.a < 1e-5) continue;
      t = (h * (2.0 * n.a / s.a - 1.0) - dot(origin, basis[2])) / denominator;
      if (t <= 0.0 || !impostorFinite(t)) continue;
      vec3 decodedNormal = n.rgb / s.a * 2.0 - 1.0;
      if (dot(decodedNormal, decodedNormal) < 1e-8) continue;
      float w = frameWeight * s.a;
      coverage += w;
      normalSum += w * normalize(decodedNormal);
      tSum += w * t;
      surfaceSum += w * s.xy / s.a;
    }
    bool valid = coverage > 1e-5 && dot(normalSum, normalSum) > 1e-10;
    // Соседние helper-фрагменты тоже должны иметь конечную нормаль для specular AA.
    vec3 objectPosition = valid ? origin + direction * (tSum / max(coverage, 1e-5)) : vec3(0.0, 0.0, vAtlasParams.y * 0.25);
    vec3 objectNormal = valid ? normalize(normalSum) : vec3(0.0, 0.0, 1.0);
    vec3 viewPosition = center + inverse(vAtlasViewToObject) * objectPosition;
    float threshold = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
    if (vFade < 0.0) threshold = 1.0 - threshold;
    float alpha = coverage * uFade * vDistanceFade;
    vec3 ringPosition = (inverse(modelViewMatrix) * vec4(viewPosition, 1.0)).xyz + uOriginOffset;
    AsteroidAppearanceProfile profile = AsteroidAppearanceProfile(uRockColor, uSpecularStrength, uSpecularPower, uSpecularTint, uLunarMix, uSurfaceAmbient);
    #ifdef USE_ICE_VARIETY
      profile = AsteroidAppearanceProfile(mix(uRockColor, uIceRockColor, vIce), mix(uSpecularStrength, uIceSpecularStrength, vIce),
        mix(uSpecularPower, uIceSpecularPower, vIce), mix(uSpecularTint, uIceSpecularTint, vIce), mix(uLunarMix, uIceLunarMix, vIce), mix(uSurfaceAmbient, uIceSurfaceAmbient, vIce));
    #endif
    vec3 color = shadeAsteroid(objectPosition * uImpostorPhysicalSize, objectNormal, transpose(vAtlasViewToObject), -viewPosition,
      vLightDirView - viewPosition, vPlanetDirView - viewPosition, vRingNormalView, ringPosition, surfaceSum / max(coverage, 1e-5),
      vInstanceSeed, vEllipse.xyz, vec2(0.0), 0.0, profile);
    if (!valid || !impostorFinite(viewPosition.z) || viewPosition.z >= 0.0 || alpha < 0.01 || abs(vFade) < threshold) discard;
    vec4 clip = projectionMatrix * vec4(viewPosition, 1.0);
    #if defined(USE_LOGARITHMIC_DEPTH_BUFFER)
      if (perspective) gl_FragDepth = log2(1.0 - viewPosition.z) * logDepthBufFC * 0.5;
      else gl_FragDepth = (clip.z / clip.w) * 0.5 + 0.5;
    #else
      gl_FragDepth = (clip.z / clip.w) * 0.5 + 0.5;
    #endif
    return vec4(color, alpha);
  }

void main() {
    vec3 atlasRayDx = dFdx(vAtlasRayPoint), atlasRayDy = dFdy(vAtlasRayPoint);
    if (vAtlasParams.z > 0.5) { gl_FragColor = renderImpostor(atlasRayDx, atlasRayDy); return; }
          #if defined( USE_LOGARITHMIC_DEPTH_BUFFER )
	gl_FragDepth = vIsPerspective == 0.0 ? gl_FragCoord.z : log2( vFragDepth ) * logDepthBufFC * 0.5;
#endif

          // Центрированные UV: (0,0) = центр, (-1,1) = края плейна
          vec2 centered = vUv * 2.0 - 1.0;

          // --- Эллипс проекции (см. вершинник) ---
          // Плейн-координаты → повернуть на -θ → нормировать на полуоси: единичный
          // диск u, в котором и силуэт, и нормаль
          vec2 p = centered * vHalfExtent;
          float cs = vEllipse.z;
          float sn = vEllipse.w;
          vec2 q = vec2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y);
          vec2 u = q / vEllipse.xy;
          float r = length(u);

          // Кромка: гармоники по углу, AA — экранными производными
          float phi = atan(u.y, u.x);
          float edge = billboardSilhouette(phi, vInstanceSeed);
          if (r > edge) discard;
          float aa = fwidth(r);
          float edgeAlpha = 1.0 - smoothstep(edge - 1.5 * aa, edge, r);

          // Нормаль масштабированной сферы: силуэт растянут до единичного диска
          // (un), z по полусфере, компоненты делятся на полуоси (нормаль сферы
          // после масштаба ∝ обратному масштабу), затем поворот обратно на +θ
          vec2 un = u / edge;
          float z = sqrt(max(1.0 - dot(un, un), 0.0));
          float rm = sqrt(vEllipse.x * vEllipse.y);
          vec3 nl = normalize(vec3(un.x / vEllipse.x, un.y / vEllipse.y, z / rm));
          vec3 normal = vec3(cs * nl.x - sn * nl.y, sn * nl.x + cs * nl.y, nl.z);

          // --- Освещение: та же модель, что у L0 (чанк AsteroidBrdf) ---
          // Билборд смотрит на камеру: view-направление ≈ +Z, поэтому NdotV = normal.z,
          // cosPhase = L.z
          float NdotL = dot(normal, vLightDirView);
          float diffuse = asteroidRegolithDiffuse(NdotL, normal.z, vLightDirView.z, mix(uLunarMix, uIceLunarMix, vIce), uOppositionSurge);
          // Тень планеты (умбра) — та же модель, что у пыли/2D-кольца/L0. Гасит
          // прямой свет; uAmbient остаётся (не в глухой ноль).
          float planetShadow = ringDustPlanetShadow(vRingPos);
          // Самозатенение слоя кольца — как у L0: прямой свет = тень планеты × тень слоя
          float direct = planetShadow * ringLayerShadow(vRingPos);
          // Planetshine планеты-хозяина — как у L0, ложится на цвет
          float shine = asteroidPlanetshine(normal, normalize(vPlanetDirView), vRingPos, uDustLightDirRing, uDustPlanetRadius);
          float lighting = uAmbient + diffuse * direct;

          // --- Итоговый цвет ---
          // vFade — плавный fade-in/out сектора; abs, т.к. знак кодирует лишь
          // направление кросс-фейда (для дизера L0), билборду важна величина.
          float alpha = edgeAlpha * uFade * vDistanceFade * abs(vFade);
          if (alpha < 0.01) discard;

          // Идентичность камня: пер-инстансный джиттер яркости, как у L0
          vec3 base = mix(uColor, uIceRockColor, vIce) * (1.0 + uColorJitter * (vInstanceSeed - 0.5) * 2.0);
          // Тинт по цвету полосы кольца — как у L0
          base *= ringBandTint(length(vRingPos.xz));
          // Planetshine — второй источник света: цвет звезды его не касается (как у L0).
          #ifdef USE_LIGHT_TINT
            vec3 color = base * uAmbient + base * diffuse * direct * uLightColor;
          #else
            vec3 color = base * lighting;
          #endif
          color += base * uPlanetshineColor * (uPlanetshineStrength * shine);
          // Подсветка от листа кольца — как у L0
          if (uRingBandEnabled > 0.5 && uRingshineStrength > 0.0) {
            float ringR = length(vRingPos.xz);
            vec3 band = ringBandAt(ringR).rgb;
            vec3 sheetColor = mix(band, pow(band, vec3(2.2)), uRingBandSrgb);
            vec3 ringshine = asteroidRingshine(normal, normalize(vRingNormalView), vRingPos, uDustLightDirRing, ringLayerTau(ringR), sheetColor, uLayerHalfThickness);
            #ifdef USE_LIGHT_TINT
              color += base * ringshine * (uRingshineStrength * planetShadow) * uLightColor;
            #else
              color += base * ringshine * (uRingshineStrength * planetShadow);
            #endif
          }
          // Аэроперспектива: дальние импосторы тонут в пылевой дымке
          color = ringDustApplyFog(color, vRingPos);
          gl_FragColor = vec4(color, alpha);
        }

