import { readFileSync, writeFileSync } from 'node:fs'
const root = 'benchmark-results/heavy-scenes/'
const originalProbe = readFileSync(root + 'production-frame-2026-10-27.browser.js', 'utf8')
writeFileSync(root + 'gpu-draws-2026-10-27.browser.js', originalProbe, { flag: 'wx' })
writeFileSync(root + 'gpu-draws-red-2026-10-27.browser.txt', originalProbe, { flag: 'wx' })
let runner = readFileSync(root + 'run-production-frame-2026-10-27.mjs', 'utf8')
runner = runner.replace("base = '49148fae5a22aaf953faadfd13bc3ac2b7e384b3'", "base = 'b36193626817edf97c980cfe312f8ebd45c81c07', sourceBase = '49148fae5a22aaf953faadfd13bc3ac2b7e384b3'")
runner = runner.replace("suffix = smoke ? '-smoke' : ''", "suffix = process.argv.includes('--red') ? '-red-smoke' : smoke ? '-smoke' : ''")
runner = runner.replaceAll('production-frame${suffix}', 'gpu-draws${suffix}')
runner = runner.replaceAll('production-frame-smoke${suffix}', 'gpu-draws-smoke${suffix}')
runner = runner.replaceAll('production-frame-2026-10-27.browser.js', 'gpu-draws-2026-10-27.browser.js')
runner = runner.replaceAll('run-production-frame-2026-10-27.mjs', 'run-gpu-draws-2026-10-27.mjs')
runner = runner.replace("git('diff', 'HEAD',", "git('diff', sourceBase,")
runner = runner.replace('const report = { base,', 'const report = { base, sourceBase,')
runner = runner.replace('sourceModuleRequests: [], outcome:', 'sourceModuleRequests: [], requests: [], outcome:')
const oldRequest = "page.on('request', r => { if (/http:\\/\\/127\\.0\\.0\\.1:8096\\/(?:src|@vite|@id|tests)\\//.test(r.url())) report.sourceModuleRequests.push(r.url()) })"
if (!runner.includes(oldRequest)) throw Error('Request guard anchor missing')
runner = runner.replace(oldRequest, `page.on('request', r => {
    const url = new URL(r.url()), route = url.pathname.replace(/^\\/titan-engine-dev(?=\\/)/, '')
    report.requests.push({ origin: url.origin, path: url.pathname, type: r.resourceType() })
    if (/^\\/(?:src|@vite|@id|tests)\\//.test(route)) report.sourceModuleRequests.push(url.origin + url.pathname)
  })`)
const start = runner.indexOf("    const windows = smoke ?")
const end = runner.indexOf('    for (const window of windows)', start)
if (start < 0 || end < 0) throw Error('Window anchors missing')
runner = runner.slice(0, start) + `    const windows = smoke ? [{ mode: 'attribution', motion: true, repetition: 0 }] : [
      { mode: 'plain', motion: true, repetition: 0 },
      { mode: 'passes', motion: false, repetition: 0 },
      { mode: 'attribution', motion: false, repetition: 0 },
      { mode: 'attribution', motion: true, repetition: 0 },
      { mode: 'passes', motion: true, repetition: 0 },
      { mode: 'plain', motion: true, repetition: 1 }
    ]
` + runner.slice(end)
// Import the same runtime and frozen dist; all old evidence stays immutable.
runner = runner.replace("console.log('PRODUCTION_FRAME',", "console.log('GPU_DRAWS',")
runner = runner.replace('JSON.stringify(result.summary)', "JSON.stringify({ intervals: result.summary.intervals, wholeCpu: result.summary.wholeCpu, scopes: Object.keys(result.summary.gpu).length, gpuSamples: result.gpu.length })")
writeFileSync(root + 'run-gpu-draws-2026-10-27.mjs', runner, { flag: 'wx' })
console.log('Prepared missing-mode control using the unchanged prior probe.')

