const root = 'benchmark-results/heavy-scenes/', base = 'b36193626817edf97c980cfe312f8ebd45c81c07', sourceBase = '49148fae5a22aaf953faadfd13bc3ac2b7e384b3'
const smoke = process.argv.includes('--smoke'), suffix = process.argv.includes('--red') ? '-red-smoke' : smoke ? '-smoke' : ''
const output = `${root}gpu-draws${suffix}-2026-10-27.json`
