const runtimePath = '/titan-engine-dev/assets/' + runtimeNames[0]
const probePath = root + 'gpu-draws-2026-10-27.browser.js'
const report = { base, sourceBase, startedAt: new Date().toISOString(), smoke, buildFiles, frozenBundle: frozen,
  sourceHashes: Object.fromEntries(await Promise.all([probePath, root + 'run-gpu-draws-2026-10-27.mjs', 'src/core/Engine.ts', 'src/core/graphic/passes/DepthVolumeResolutionRenderer.ts', 'src/core/graphic/passes/DepthVolumeReconstructionRenderer.ts'].map(async p => [p, sha(await readFile(p))]))),
  rows: [], scenes: [], errors: [], warnings: [], assetFailures: [], abortedRequests: [], cloudResponses: 0, sourceModuleRequests: [], requests: [], outcome: 'failed' }
