// Read-only-in-effect experiment: temporary pass toggle on the existing production runtime.
const runtime = await import('/titan-engine-dev/assets/simulationRuntime-CkDXyoW-.js')
const get = name => {
  const container = runtime.getInitializedSimulationRuntime().container
  const keys = [...container.bindings.keys()].filter(key => typeof key === 'object' && key.name === name)
  if (keys.length !== 1) throw Error('Missing production service ' + name)
  return container.get(keys[0])
}
const encoded = bytes => {
  let value = ''
  for (let i = 0; i < bytes.length; i += 16384) value += String.fromCharCode(...bytes.subarray(i, i + 16384))
  return btoa(value)
}
window.__lensSkipExperiment = async () => {
  const engine = get('Engine'), renderer = get('Renderer'), gl = renderer.getContext(), pp = get('Postprocessing')
  const lens = pp.composer.passes[4], registry = get('LensRegistry')
  if (registry.size !== 0 || lens.name !== 'EffectPass') throw Error('Experiment requires empty lens registry')
  const enabled = lens.enabled, records = []
  engine.stop()
  try {
    for (const [label, skip] of [['baseline-before', false], ['candidate-skip', true], ['baseline-after', false]]) {
      lens.enabled = !skip
      for (const pass of pp.composer.passes) {
        const history = pass.scaled?.history
        if (history) for (const frame of history.records.values()) history.invalidate(frame)
      }
      for (let frame = 0; frame < 16; frame++) pp.render(0)
      const pixels = new Uint8Array(gl.drawingBufferWidth * gl.drawingBufferHeight * 4)
      gl.readPixels(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight, gl.RGBA, gl.UNSIGNED_BYTE, pixels)
      const error = gl.getError()
      if (error !== gl.NO_ERROR) throw Error('WebGL error in image experiment: ' + error)
      records.push({ label, skip, width: gl.drawingBufferWidth, height: gl.drawingBufferHeight,
        rgba: encoded(pixels), png: renderer.domElement.toDataURL('image/png').split(',')[1] })
    }
    return { registrySize: registry.size, multisampling: pp.composer.multisampling, records,
      caveat: 'Frozen scene via stopped engine, postprocessing.render(0), volume histories reset to phase0 before each 16-frame sequence. Baseline-before/after controls determinism. This is a temporary toggle experiment, not shipped code or a performance result.' }
  } finally { lens.enabled = enabled; engine.start() }
}

